source='''def transform(grid):
    h, w = len(grid), len(grid[0])
    seen = set()
    seeds = set()

    for r in range(h):
        for c in range(w):
            if grid[r][c] != 3 or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            cells = []
            while stack:
                y, x = stack.pop()
                cells.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    yy, xx = y + dy, x + dx
                    if (0 <= yy < h and 0 <= xx < w and grid[yy][xx] == 3
                            and (yy, xx) not in seen):
                        seen.add((yy, xx))
                        stack.append((yy, xx))
            r0 = min(y for y, _ in cells)
            r1 = max(y for y, _ in cells)
            c0 = min(x for _, x in cells)
            c1 = max(x for _, x in cells)
            for y in range(r0, r1 + 1):
                for x in range(c0, c1 + 1):
                    if grid[y][x] == 2:
                        seeds.add((y, x))

    out = [row[:] for row in grid]
    for y, x in seeds:
        for yy in range(max(0, y - 1), min(h, y + 2)):
            for xx in range(max(0, x - 1), min(w, x + 2)):
                out[yy][xx] = 1
    for y, x in seeds:
        out[y][x] = 2
    return out
'''
